/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    isEncryptedSave, saveEncryptionKeys, encryptedSaveParts, unmaskSave, decryptSave
 * depends    —
 * used by    src/node/decrypt-save, src/save-decoder/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
/** Reads the authenticated TDS1 container before the ordinary gzip/NRBF reader. */
const MAGIC = [0x54, 0x44, 0x53, 0x31]
const HEADER_SIZE = 53
const PRIMARY_KEY_MULTIPLIER = 2654435761
const SECONDARY_KEY_SEED = 668265263
const MASK_HASH_SEED = 2166136261
const MASK_HASH_MULTIPLIER = 16777619
const MASK_MULTIPLIER = 1664525
const MASK_INCREMENT = 1013904223
const MASK_KEY = Uint8Array.from([
  0x35, 0x57, 0x9b, 0x22, 0x8d, 0xb6, 0x1a, 0x72,
  0xec, 0x95, 0xc0, 0x97, 0x80, 0x20, 0x2a, 0x9b,
  0xfa, 0xcb, 0x0c, 0x74, 0x0c, 0x05, 0x2b, 0xd4,
  0xe8, 0x3b, 0xe8, 0x82, 0xf3, 0xd8, 0xec, 0x5d,
])

export function isEncryptedSave(bytes: Uint8Array): boolean {
  return bytes.length >= 4 && MAGIC.every((value, index) => bytes[index] === value)
}

/** The two deterministic 256-bit keys used by the save container. */
export function saveEncryptionKeys(): { encryption: Uint8Array; authentication: Uint8Array } {
  const encryption = new Uint8Array(32)
  const authentication = new Uint8Array(32)
  let primary = PRIMARY_KEY_MULTIPLIER
  let secondary = SECONDARY_KEY_SEED
  for (let i = 0; i < 32; i++) {
    primary = Math.imul(primary ^ (7 + i * 131), PRIMARY_KEY_MULTIPLIER) >>> 0
    primary = (primary ^ (primary >>> 15)) >>> 0
    encryption[i] = i * 29 + primary
    secondary = Math.imul(((secondary >>> 25) | (secondary << 7)) ^ (11 + i * 97), 0x9e37) >>> 0
    authentication[i] = (i * 53) ^ (secondary >>> 11)
  }
  return { encryption, authentication }
}

export function encryptedSaveParts(input: Uint8Array) {
  // Own the bytes across async crypto calls so callers cannot alter authenticated data.
  const bytes = Uint8Array.from(input)
  if (bytes.length < HEADER_SIZE) throw new Error('This encrypted save file is incomplete.')
  if (bytes[4] !== 1) throw new Error(`Unsupported encrypted save version: ${bytes[4]}.`)
  const ciphertext = bytes.slice(HEADER_SIZE)
  if (!ciphertext.length || ciphertext.length % 16 !== 0) {
    throw new Error('This encrypted save file is incomplete or corrupt.')
  }
  const authenticated = new Uint8Array(17 + ciphertext.length)
  authenticated.set(bytes.subarray(4, 21))
  authenticated.set(ciphertext, 17)
  return { iv: bytes.slice(5, 21), mac: bytes.slice(21, HEADER_SIZE), ciphertext, authenticated }
}

/** Reverse the byte mask applied to the compressed payload before encryption. */
export function unmaskSave(bytes: Uint8Array): Uint8Array {
  let state = MASK_HASH_SEED
  for (const value of MASK_KEY) state = Math.imul(state ^ value, MASK_HASH_MULTIPLIER) >>> 0
  for (let i = 0; i < bytes.length; i++) {
    state = (Math.imul(state, MASK_MULTIPLIER) + MASK_KEY[i & 31] + MASK_INCREMENT) >>> 0
    const mask = (MASK_KEY[(i * 5 + 3) & 31] ^ (state >>> 24) ^ (state >>> 9)) & 255
    const shift = (state >>> 6) & 7
    const rotated = ((bytes[i] >>> shift) | (bytes[i] << (8 - shift))) & 255
    bytes[i] = ((rotated - (state >>> 13)) & 255) ^ mask
  }
  return bytes
}

export async function decryptSave(bytes: Uint8Array): Promise<Uint8Array> {
  if (!isEncryptedSave(bytes)) return bytes
  const parts = encryptedSaveParts(bytes)
  const subtle = globalThis.crypto?.subtle
  if (!subtle) throw new Error('Encrypted saves require Web Crypto. Open this tool in a secure browser context.')
  const keys = saveEncryptionKeys()
  const macKey = await subtle.importKey('raw', keys.authentication as BufferSource, { name: 'HMAC', hash: 'SHA-256' }, false, ['verify'])
  if (!await subtle.verify('HMAC', macKey, parts.mac, parts.authenticated)) {
    throw new Error('This encrypted save failed its integrity check. Copy it again and retry.')
  }
  const aesKey = await subtle.importKey('raw', keys.encryption as BufferSource, 'AES-CBC', false, ['decrypt'])
  let plaintext: ArrayBuffer
  try {
    plaintext = await subtle.decrypt({ name: 'AES-CBC', iv: parts.iv }, aesKey, parts.ciphertext)
  }
  catch {
    throw new Error('This encrypted save could not be decrypted.')
  }
  return unmaskSave(new Uint8Array(plaintext))
}
